import{_ as s,c as t,o as n,j as a,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"汉上先生履历","description":"汉上易传 - 汉上先生履历","frontmatter":{"title":"汉上先生履历","description":"汉上易传 - 汉上先生履历"},"headers":[],"relativePath":"zh/classics/hanshang/013.md","filePath":"zh/classics/hanshang/013.md"}'),l={name:"zh/classics/hanshang/013.md"};function c(o,e,i,d,h,p){return n(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"汉上先生履历",tabindex:"-1"},[r("汉上先生履历 "),a("a",{class:"header-anchor",href:"#汉上先生履历","aria-label":"Permalink to “汉上先生履历”"},"​")],-1),a("p",null,"除春秋博士告词：敕迪功郎朱震：孔子曰：吾志在春秋。又曰：知我者其惟春秋乎。是经之不用于世，果遵何说哉？朕比诏立学官，用以取士，命汝往处师席。尔其推明三家之同异，与诸生切磨，以求合于圣人之意，罔俾汉儒专以名家，则称朕旨。可特授依前官守太学春秋博士。靖康元年五月九日，除太学春秋博士告词：敕宣教郎朱震：孔子作春秋而乱臣贼子惧，岂特当时为然，使千百载之后犹凛然畏之，此经所以久郁而不明也。朕比命列子博士训迪诸生，尔以修洁该洽而膺是选，必能明圣人作经之旨，使学者有考焉。勉称厥职，予则汝嘉。可特授依前宣教郎、太学春秋博士填见阙。靖康元年十月二十日除秘书郎告词。敕：宣教郎、太学博士朱震中：秘雠书极天下豪俊之选，异时贵臣用事，至参用医卜之流，牛骥同群，可为太息。肆朕初载，遴柬儒术之英。尔以文艺有闻，首置兹选。进与群髦之列，益观未见之书。三箧巳亡，且询安世。勉思刻厉，将有试焉。可特授依前宣教郎、秘书省校书郎。靖康元年十一月六日，除祠部员外郎。告词。敕：左宣教郎朱震：朕旁求俊乂，列置文昌，非徒使之分职率属，允厘庶事。而众正在位，则朝廷自尊。尔涉道精淳，存心乐易，强学力行，白首不衰。闻望之休，溢于予听。嘉其敷奏之美，喜见德人之容。郎选甚高，祠曹务简。往共乃职，体朕眷私。可特授依前官守尚书祠部员外郎。绍兴四年十月五日除秘书少监告词。敕左奉议郎、守尚书祠部员外郎朱震。朕惟否泰二卦，论君子小人消长之理甚明。或者谓消长系乎时数，此大不然。上下交而其志同，于时为泰，故君子以其汇征。上下不交而天下无邦，于时为否，故君子以俭德避难而巳。尔学古通经，特立守正，粹然君子人也，固穷乡闾，累经除召。今者惠然肯来，就我荣禄。朕以尔之避就，卜时否泰，其庶几焉。蓬山宝藏，乃今日养才之地也，用尔为贰，盖不徒然。朕知尔旧矣，奚俟深训。可特授依前官试秘书少监。绍兴五年二月十六日，除秘书少监兼侍讲告词。左奉议郎、试秘书少监朱震可特授依前左奉议郎、试秘书少监、兼侍讲、左朝奉大夫、守宗正少卿、兼直史馆范冲等：学之为王者事，其巳久矣。虽二帝三王，盖尝汲汲于此。朕于国家多艰之际，不废祖宗故事，爰命儒学之臣，环侍便坐，讲经史，敷求政礼，以广聪明。尔等操履端方，学问该洽，通今古，达于治乱之原，其必有裨。吾不逮宜，自卿监之联，兼陪经幄之职，益思报称，以副旁求。可依前件。绍兴五年闰二月五日转承议郎告词。敕左奉议郎、试秘书少监兼侍讲朱震：朕纂极之初，推旷荡之泽，士大夫京秩而上，例进一等，盖祖宗旧制也。尔方投闲在远，积有岁年，而恩未沾及，恬退之风，有足嘉者。序进厥官，往其祗服。可特授左承议郎，依前秘书少监兼侍讲。绍兴五年三月九日除起居郎。告词：敕左承议郎、秘书少监兼侍讲朱震：孔子称天下归仁，曰：非礼勿言，非礼勿动。人君托于王公之上，一言一动，则必记之。是欲克巳复礼，俾天下之归也。设官之意，其深矣乎！以尔习于春秋，明乎褒贬，经筵劝讲，开益为多。命尔立螭，记予言动。官分左右，职固不殊。朕知戒非礼之为，尔其谨必书之职。可特授依前左承议郎、守起居郎、兼侍讲。绍兴五年五月三日，除兼资善堂赞读告词。敕左承议郎、守起居郎、兼侍讲、赐绯鱼袋朱震：朕惟蒙之",-1),a("p",null,"象曰：山下出泉，蒙，君子以果行育德。盖泉之初，未有所之，如人之蒙，未知所适。泉决之东西，蒙导之邪正。亦惟其人而巳矣。以尔纯白内备。博见洽闻。羲易麟经。尤所精贯。华光劝讲。宏益滋多。方开学于南宫。久注心于旧德。赞读资善。汝往惟谐。既正朕之不难。宜诲蒙之无倦。兼职虽众。应用莫穷。勿嫌拜赐之频。实繄稽古之力。其益懋哉。可特授依前官兼侍讲兼资善堂赞读。绍兴五年六月三日除中书舍人兼资善堂翊善告词。敕：昔者周穆继南征之后，无讨贼之心。逮乎平王为东迁之君，无兴复之志。观其告命，泰然与成康之世无异，君子是以知周德之衰矣。乌乎。有能宣吾恻怛难喻之情，如建武奉天诏书，以助中兴之功者乎？左朝奉郎、守起居郎、兼侍讲、兼资善堂赞读、赐绯鱼袋朱震，学博而造深，行和而志正，以道献替，简于朕心。升擢纶诰之司，仍卒金华之业，尚贤西学，谕教如初。夫士以得君为难，而朕之知汝者厚矣。论思润色，尚往钦哉。必无媿于古人，乃有辞于永世。可特授依前官、试中书舍人、兼侍讲、兼资善堂翊善。绍兴五年八月十七日，转朝散郎。告词。敕：典谟训诰，皆上古之书；笔削春秋，著先王之志。其文虽史，垂世为经。朕仰奉孙谋，恭绳祖武。览裕陵之实录，悼私史之谤言。譬夫氛祲之兴，或掩昭回之象。乃诏群彦，同次旧文。左朝奉郎、试中书舍人兼侍讲，兼资善堂翊善、赐紫金鱼袋朱震，学贯九流，趋皇极会归之要；识深五传，穷古人述作之原。顷预编摩，克严去取，兹阅奏篇之上，弥嘉汗简之劳。十九年之勋德既昭，千万世之楷模斯在。祖宗有庆，非出朕私，爵秩所加，式为尔宠。名附不刊之典，实彰有永之辞。可特授左朝散郎，依前试中书舍人。绍兴五年十月七日，转左朝请郎告词。敕：朕惟帝王之治，求端于天。是以察璇玑者协时月正日，陈洪范者省岁月日时。本天理而时措之，后王用智力而持世曲学，判天人为两途。凡历象授民之妙，散为术家。至于闰余失次，摄提无纪，以为是固然，而不知其拂天害民，乱之大者也。左朝散郎、试中书舍人、兼侍讲、兼资善堂翊善、赐紫金鱼袋朱震，学深象数，智潜幽眇，会于道要，得其本原。属历法之有差，视筭家而参正。成书来上，七政以齐。虽史迁之起太初，子云之明三统，不得专美，予用嘉之。序进一官，少旌劳绩，是谓德赏，往其钦承。可特授左朝请郎，余依前。绍兴五年十月二十二日除给事中告词。敕：自昔有事殿内之臣，不过侍左右、掌顾问而巳，然犹遴择名儒，以充此选。矧今万务出入，皆属东台，时当艰危，动关兴废。其或行事不协于中，任官不厌于众，虽有君命，皆得駮而正之，其职可谓重矣。肆求闻人，今以命汝。左朝请郎、试中书舍人兼侍讲、兼资善堂翊善，赐紫金鱼袋朱震，学际天人，识穷理乱，年德俱懋，望实素隆。演诰西垣，荣问益畅，进司琐闼，公议允谐。夫纠其乖违，俾庶政孚于群听；审其奏述，使下情得而上通，则朕为得人，而汝为称职，岂不休哉！可特授依前左朝请郎、试给事中，余如故。绍兴六年正月十六日，转左朝奉大夫告词：敕：朕深惟国本，茂建宗支。朝夕端士之亲，冀性习于为善；博约前言之识，俾学富于多闻。聿就终篇，可无褒律。翰林学士、左朝请郎、知制诰、兼侍读、兼资善堂翊善、赐紫金鱼袋朱，　心潜六艺，文贯九流。廷论倚如蓍龟，正人赖为领袖。雍容视草，何独润色之工；密勿告猷，备罄论思之益。属宗藩之谕教，嘉术业之向成。畴稽古之勤，既车服之是锡。懋增秩之渥，抑典故之具存。尚坚调护之功，用究师儒之效。眷予耆艾，奚假训词。可特授左朝奉大夫，依前翰林学士、知制诰，余如故。绍兴六年十一月三日，乞宫观差遣不允。诏敕：朱　省札子奏乞除一在外宫劝差遣事，具悉。朕以王教存乎篇籍，方儒学之是咨；老成重于典刑，实朝廷之所赖。故详延于瑰硕，以参劘于古今。卿道术深明，文辞英妙。耆名高义，足以为群士之羽仪；博物洽闻，足以备一时之访问。禁林递直，岁律载周。侍经幄之燕间，谨宗藩之训导。国侨润色，非有官职之甚劳；陆䞇腹心，尚倚神明之克壮。奉身而退，匪朕所闻，其体眷怀，母重来请所请宜不允，仍不得再有陈请。故兹诏示，想宜知悉。再乞宫观，不允。诏：卿文足以达意，学足以明理，行足以正人。兼是三者，故处以视草横经之地，且使从吾嗣子之游，既有年矣。遽览奏章，引疾丏外，辞意甚切，朕为之动心焉。夫德齿俱懋，固平日之所尊；气体失平，亦老者之常事。姑务休养，以期清明，使朝廷之所宝惟贤，则四方必仰朕之德，岂小补哉！所请宜不允。故兹诏示，想宜知悉。辞免翰林学士。不允。诏敕：朱　省所奏辞免翰林学士、知制诰恩命事，具悉。昔陆䞇为学士，国有大政，参裁可否，兴元戡难之功，实多文怀之助。卿学造壸域，识通系表，文章典雅，无愧昔人，议论坚明，有补当世。越朕初载，杖策军门，谊先国家，节贯华皓。老成在服，厥有典刑。俾代予言，以纾素缊。岂特资其讨论润色之益，亦将托以腹心耳目之寄焉。尚执谦㧑，殆非所望。亟共乃服，母复费辞。所请宜不允。故兹诏示，想宜知悉。再乞宫观，不允。诏敕朱　乞除在外宫观事，具悉。卿学高诸儒，名映一代。从朕艰难之际，实惟旧人。蔼然德义之风，信于多士。契阔累岁，登崇近班。大册高文，佐时戡难。博物强记，益朕多闻。国有老成，众无异论。朕方知九德之行，灼见三俊之心，庶无遗材，用齐多故。虽山林隐居之士，尚当结绶而来；顾朝廷领袖之贤，乃欲奉身而去。况神明之克壮，何疾病之可言。览观来章，殊咈朕眷。勉安厥位，母复有云。所请宜不允。故兹诏示，想宜知悉。辞免建国公、听读尚书终篇恩命不允。诏：𢽟朱　所奏辞免转一官恩命事具悉。朕择本支以隆国势，修劝导而备官司，其有成劳，可无褒命。卿经术深懿，独高诸儒，德性纯明，自倾多士。为时耆旧，适副简求，日陈道义之言，助子诗、礼之训。肆稽故事，以宠毕章。朕方擢先王厉世之规，通天下赴功之志，虽疏远之吏，摽末之庸，并录不遗，以劝为善。况如卿者，其可辞乎？何为上书，遽求反令，固难曲徇其趣。钦承所请。宜不允。再辞，不允。诏：朕以卿道艺深明，行能高妙，传授经业，训迪宗藩。俾通上古之书，宜从增秩之赏。而乃屡陈悃愊，力避宠荣。夫尊贤显功，盖人主驭臣之柄；而难进易避，亦师儒厉俗之规。使勤劳而见知者尚或固辞，则虚伪而幸进者庶几有耻。豆惟勉从于尔志，抑亦少劝于士风。载亮冲怀，不忘嘉叹。乞宫观。不允。诏：朕寤怀英贤，共图康济。虽山林隐逸之士，尚不倦于招徕；矧朝廷耆艾之儒，岂忍使其轻去。卿学穷圣域，行允廷佥，论必据经，文推华国。扬，历禁涂之久，备观辰告之忠。不独朕知卿之既深，亦惟卿守义之甚固。老成在列，多士朋来，胡为抗章，遽欲引退。与其洁身而辞位，希廉士之风；熟若尽道以致君，卒贤人之业。勉体至意，母重有陈。所请宜不允赠官告词。𢽟！死生之道，通乎昼夜，达者以为当然；君臣之义，笃于始终，有国以为令典。逮此告终之问，敢忘哀赠之恩。故翰林学士、左朝奉大夫致仕、长林县开国男、食邑三百户、赐紫金鱼袋朱，　蚤以词华，亟跻脢仕，晚由学术，荐更禁涂。惊怛化之无常，怅徽音之如在，子有憖遗之感，人怀殄瘁之悲。考于故常，申此赠典。百身可赎，兴怀不朽之规；一鉴云亡，徒有无从之涕。精爽不昧，宜歆此恩。可特赠左中大夫，余如故。绍兴八年七月三日回。朱八行子发启。　　　　　胡文定公 安国。 荐章交剡，公议甚孚。凡属俊游，共欣荣问。学正八行赋才雄骜，受业精通。手披万卷之书，要归卓约；笔扫千军之阵，耻尚浮华。有言必务于躬行，所得多繇于心了。家庭素履，岂求闻达之方。郡国诸侯，乐任宾兴之职。夜鹤不惊于佩帐，大鹏正假于扶摇。言念迂愚，久敦情好。论交莫逆，固蕲美誉之彰；惩沸误吹，初绝游谈之助。盍相忘于微笑，尚伸贶于长笺。过形引重之词，弥服推先之义。然贤者名高而责备，物情利及而争归。圣门之实学难穷，人境之虚荣易惑。平居把袂，最钦松桂之姿。得路彯缨，更砺冰霜之节。证明吾道，倚仗英摽。祭文：维绍兴八年岁次戊午七月庚申朔十七日辛丑，左朝散郎、试尚书吏部侍郎、兼详定一司𢽟令晏敦复、左朝散大夫、试尚书户部侍郎、兼详定一司𢽟今李弥逊，左中大夫、试尚书礼部侍郎曾开，左朝请郎、试尚书兵部侍郎张焘，左朝奉大夫、新除尚书兵部侍郎、兼资善堂翊善、兼侍讲吴圭，左朝奉大夫、试给事中兼侍讲张致远，左朝奉大夫试给事中兼史馆修撰勾涛，左朝奉郎试中书舍人兼直学士院兼侍讲吕本中，左朝请郎试中书舍人楼炤，左朝请郎试中书舍人勾龙如渊、左朝请郎权尚书吏部侍郎魏玒，左奉议郎权礼部侍郎张九成，谨以清酌庶羞之奠，致祭于故侍读内翰翊善朱公之灵。惟公老于田亩，困于州县，白首穷经，意则不倦。视彼世人，奚贵奚贱。不义而得，吾亦不愿。一昨召来，遇知明主。金马玉堂，四涉寒暑。以经决事，随事有补。位高职卑，亦莫公侮。不传之要，自得之妙。惟公知之，固世所笑。彼笑何伤，公亦自强。愈老愈壮，虽死不亡。识公日浅，相知则深。公病不起，孰不痛心。凉风应时，白露日侵。薄酒寓哀，公或肯临。尚飨。",-1),a("p",null,"宋朱震撰。按震表进是书，谓马、郑、荀、虞各自名家，说虽不同，去象数之源未远。独魏王弼尽去旧说，杂以庄、老之言，于是儒者专尚文辞，不复推原大传，天人之道，分裂不合。又历举宋世诸儒宗旨，谓或明其象，或论其数，或传其辞，或兼而明之。复自称获观遗书，粗窥一二，撰为是书，以易传为宗，和会雍载之论，上采汉、魏、吴、晋、元魏，下逮有唐及今，包括异同，补苴罅漏云云。其后诸儒评论，互有褒贬，或讥其谬妄，或谓其不可废。四库著录通志堂经解，亦经采刊。惟均附卦图三卷、丛说一卷，是为南宋旧刊。影自北平图书馆，存易传九卷，佚卷一、二及卷五若干叶。补以毛氏汲古阁影抄本。按文渊阁书目载是书一部三册，一部十册，均阙，毛氏影抄，亦佚卦图丛说。盖宋本散佚已久，今不可复见，且集传首尾完具，故影印之，以饷世之嗜读古书者。民国纪元二十三年十月，海盐张元济",-1)])])}const f=s(l,[["render",c]]);export{_ as __pageData,f as default};
